/**
 * river-basins data: North Carolina's 17 major river basins, their rivers and creeks (with tributary
 * order), lakes and reservoirs, inset shapes, and the state outline. Imported only by v1.ts. Frozen with
 * v1 (ADR 0021): a change here redraws locked sites, so new data means a new data file for a new version.
 *
 * Basins: the 17 basins are defined in G.S. 143-215.8B(f) (as amended by S.L. 2021-158) as the North
 * Carolina portion of listed USGS cataloging units; drawn from the USGS Watershed Boundary Dataset HUC-8
 * polygons (public domain), unioned per basin and clipped to North Carolina's land and inland water (the
 * Census 2024 TIGER state boundary split along the Census coastline, so the 3-mile territorial sea is left
 * out). The areas are computed from that geometry on the NC State Plane projection. Rivers and creeks
 * © OpenStreetMap contributors (ODbL 1.0, https://www.openstreetmap.org/copyright); a creek's parent is
 * the river its mouth meets (OSM waterways point downstream), giving the tributary order. Lakes
 * © OpenStreetMap contributors. State outline, U.S. Census Bureau (public domain).
 *
 * Projection and encoding as county-survey's data: NC State Plane, quantized to 20 m, delta-encoded
 * (`decLine` in plotter/v1.ts); several rings in one string are separated by "!".
 */

/** One basin: key, title, where it drains, area (sq mi), HUC-8 units, outline, rivers, lakes, inset shape. */
export interface BasinRecord {
  id: string;
  t: string;
  f: string;
  a: number;
  h: number;
  o: string;
  /** [name index, order (0 = main stem), parts]. */
  r: [number, number, string][];
  /** [name index, rings]. */
  l: [number, string][];
  i: string;
}

export interface BasinData {
  U: number;
  O: number[];
  B: BasinRecord[];
  N: string[];
  LN: string[];
  NC: string;
  NCI: string;
}

